// ---- 0x01 hello: greet the device; required before any other command --------
export type HelloRequest = Record<string, never>;
export type HelloReplyFields = { info: string };
export type HelloReply = Reply<HelloReplyFields, never>;
export function encodeHelloRequest(): Uint8Array {
  return new Uint8Array(0);
}
export function decodeHelloRequest(payload: Uint8Array): HelloRequest {
  return decodeRequest(COMMANDS["hello"], payload) as HelloRequest;
}
export function encodeHelloReply(reply: HelloReply): Uint8Array {
  return encodeReply(COMMANDS["hello"], reply);
}
export function decodeHelloReply(payload: Uint8Array): HelloReply {
  return decodeReply(COMMANDS["hello"], payload) as HelloReply;
}

// ---- 0x02 diag.status: device counters as tagged binary blocks --------------
export type DiagStatusRequest = Record<string, never>;
export type DiagStatusReplyFields = { blocks: Uint8Array };
export type DiagStatusReply = Reply<DiagStatusReplyFields, never>;
function encodeDiagStatusRequest(): Uint8Array {
  return new Uint8Array(0);
}
function decodeDiagStatusRequest(payload: Uint8Array): DiagStatusRequest {
  return decodeRequest(COMMANDS["diag.status"], payload) as DiagStatusRequest;
}
function encodeDiagStatusReply(reply: DiagStatusReply): Uint8Array {
  return encodeReply(COMMANDS["diag.status"], reply);
}
function decodeDiagStatusReply(payload: Uint8Array): DiagStatusReply {
  return decodeReply(COMMANDS["diag.status"], payload) as DiagStatusReply;
}

// ---- 0x03 file.read: read a file, whole (at most 4096 bytes) or a range -----
export type FileReadRequest = { path: string; offset?: undefined; length?: undefined } | { path: string; offset: number; length: number };
export type FileReadReplyFields = { data: Uint8Array };
export type FileReadReply = Reply<FileReadReplyFields, never>;
